<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import AdminDialog from './AdminDialog.vue';import UserAccessFields from './UserAccessFields.vue';import LegacyPmsInvitations from './LegacyPmsInvitations.vue';
const props=defineProps<{data:any;csrf?:string;startOpen?:boolean}>();const query=ref(''),filter=ref('all');const legacy=ref(false);const rows=ref<any[]>([]),open=ref(!!props.startOpen),busy=ref(false),error=ref(''),message=ref(''),link=ref('');
const empty=()=>({name:'',email:'',product_slugs:[] as string[],company_ids:[] as number[],communication_admin:false,pms_role_ids:[] as number[],pms_department_ids:[] as number[],group_ids:[] as number[],pms_task_ids:[] as number[],delivery_method:'manual'});const form=ref(empty());
const shown=computed(()=>rows.value.filter(row=>(row.email+' '+(row.name||'')).toLowerCase().includes(query.value.toLowerCase())&&(filter.value==='all'||status(row)===filter.value)));
async function request(path='',body?:any){const r=await fetch('/admin/api/invitations'+path,{method:body?'POST':'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.errors?Object.values(d.errors).flat().join(' '):d.message);return d;}
async function load(){try{rows.value=(await request()).invitations;}catch(e){error.value=(e as Error).message;}}
async function send(){busy.value=true;error.value='';link.value='';try{const body={...form.value,communication_admin:form.value.product_slugs.includes('communication')&&form.value.communication_admin,group_ids:form.value.product_slugs.includes('communication')?form.value.group_ids.filter(id=>props.data.groups.some((g:any)=>g.id===id&&form.value.company_ids.includes(g.company_id))):[]};const d=await request('',body);message.value=d.message;link.value=d.invitation_url;open.value=false;form.value=empty();await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function revoke(row:any){if(!confirm('Revoke the invitation for '+row.email+'?'))return;busy.value=true;error.value='';try{message.value=(await request('/'+row.id+'/revoke',{})).message;await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function status(row:any){return row.accepted_at?'Accepted':row.revoked_at?'Revoked':Date.parse(row.expires_at)<Date.now()?'Expired':'Pending';}
async function copy(){try{await navigator.clipboard.writeText(link.value);message.value='Invitation link copied.';}catch{error.value='Copy the invitation link from the field.';}}
onMounted(()=>{void load();const entry=new URLSearchParams(location.search);if(entry.get('invite_email')){form.value.email=entry.get('invite_email')||'';form.value.product_slugs=['projects'];const task=Number(entry.get('invite_task'));if(props.data.pms_tasks.some((t:any)=>t.id===task))form.value.pms_task_ids=[task];open.value=true;}});
</script>
<template><div class="admin-section-heading"><div><h2>Employee invitations</h2><p class="muted">One account, one invitation, multiple products. Existing users keep their password and current product access.</p></div><button class="button primary" @click="open=true;error='';link=''">Invite employee</button></div><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p>
<AdminDialog v-if="open" title="Invite to Judibas" subtitle="Choose products and access. The recipient uses one account." :busy="busy" @close="open=false"><form class="admin-editor" @submit.prevent="send"><div class="admin-form-grid"><label>Email<input type="email" v-model="form.email" required maxlength="200"></label><label>Name (optional)<input v-model="form.name" maxlength="100"></label></div><UserAccessFields :value="form" :data="data"/><label>Delivery<select v-model="form.delivery_method"><option value="manual">Create secure link</option><option value="email">Send by email</option></select></label><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><div class="editor-actions"><button class="button primary" :disabled="busy">{{busy?'Creating...':'Create invitation'}}</button><button type="button" class="button" :disabled="busy" @click="open=false">Cancel</button></div></form></AdminDialog>
<div v-if="link" class="admin-editor admin-share-link"><label>Secure invitation link<input :value="link" readonly></label><button class="button" @click="copy">Copy link</button></div>
<div class="admin-invitation-stats"><span><strong>{{rows.length}}</strong> invitations</span><span><strong>{{rows.filter(r=>status(r)==='Pending').length}}</strong> pending</span><span><strong>{{rows.filter(r=>status(r)==='Accepted').length}}</strong> accepted</span></div><div class="admin-filterbar admin-invite-filters"><label class="admin-search-field"><span>Search invitations</span><input v-model="query" type="search" placeholder="Search name or email..."></label><label><span>Invitation status</span><select v-model="filter"><option value="all">All invitations</option><option v-for="state in ['Pending','Accepted','Expired','Revoked']" :key="state">{{state}}</option></select></label></div><div class="admin-list"><p v-if="!shown.length" class="empty-state">{{rows.length?'No invitations match your filters.':'No invitations yet. Invite an employee to get started.'}}</p><article v-for="row in shown" :key="row.id"><div><strong>{{row.name||row.email}}</strong><p>{{row.email}}</p><p class="muted">{{row.access.product_slugs.map((slug:string)=>data.products.find((p:any)=>p.slug===slug)?.name||slug).join(', ')}}</p><div class="admin-invite-status"><span class="admin-status" :class="status(row)==='Accepted'?'is-active':status(row)==='Pending'?'admin-product-chip':'is-inactive'">{{status(row)}}</span><span class="muted">{{row.delivery_status.replaceAll('_',' ')}}</span></div></div><button v-if="status(row)==='Pending'" class="button" :disabled="busy" @click="revoke(row)">Revoke</button></article></div>
<details class="admin-editor"><summary>Previous PMS invitations</summary><p class="muted">Existing task and employee invitations continue to use their original acceptance links.</p><a href="/admin#legacy-pms-invitations" @click.prevent="legacy=!legacy">View previous PMS invitations</a><LegacyPmsInvitations v-if="legacy"/></details>
</template>
